contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take parameters: a source address 'from', a target contract 'caddress',
    // an array of addresses '_tos' and a value 'v'.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        // Perform the call and capture whether it reverted.
        bool reverted;
        bool returned;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }
        // The general rule: transfer succeeds (returned==true and not reverted) exactly when none
        // of the internal low-level calls reverted. We cannot observe internal calls directly,
        // but we can check that if transfer did not revert it returned true per implementation,
        // and if it reverted we observe reverted==true. Thus assert equivalence between reverted and returned.
        // More precisely: for this implementation, if the call did not revert it must return true.
        assert(reverted == (!returned));
    }
    receive() external payable { }
}

